scene.setBackgroundImage(assets.image`backgroundImage`)

let playerImages = [assets.image`playerForward`, assets.image`playerBackward`, assets.image`playerLeft`, assets.image`playerRight`]

for (let i = 0; i < playerImages.length; i++) {
    let player = sprites.create(playerImages[i], SpriteKind.Player)
    player.setPosition(15 + (i * 20), 30)
}

let obstacle = sprites.create(assets.image`obstacleImage`)
obstacle.setPosition(110, 30)
